import{_ as o,o as n,c as a,a0 as t}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Kỹ năng: /configure-repo-maps","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/configure-repo-maps.md","filePath":"references/skills/configure-repo-maps.md"}'),c={name:"references/skills/configure-repo-maps.md"};function i(r,e,s,l,h,p){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="ky-nang-configure-repo-maps" tabindex="-1">Kỹ năng: <code>/configure-repo-maps</code> <a class="header-anchor" href="#ky-nang-configure-repo-maps" aria-label="Permalink to &quot;Kỹ năng: `/configure-repo-maps`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>configure-repo-maps</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/configure-repo-maps</code>.</li><li>Nhập kèm yêu cầu bằng ngôn ngữ tự nhiên (NL) chỉ định các đường dẫn (paths) tới thư mục repo trên máy tính (ví dụ: <code>docs = base-docs ở ~/ws/base-docs, portal admin ở ~/ws/portal</code>).</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Mô tả bằng ngôn ngữ tự nhiên của member về vị trí checkout các repo thuộc hệ thống (Platform) hoặc hệ thống cũ (Legacy).</li><li>File cấu hình map hiện tại: <code>platform-repos.local.json</code> hoặc <code>legacy-repos.local.json</code>.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li><strong>Cập nhật Map:</strong> Ghi các đường dẫn (được chuẩn hóa sang dạng tuyệt đối absolute path) vào file <code>platform-repos.local.json</code> (cho platform/hub hiện tại) hoặc <code>legacy-repos.local.json</code> (cho repo legacy).</li><li><strong>Không xâm lấn:</strong> Tuyệt đối không gọi <code>git clone</code>/<code>git fetch</code> hay kết nối remote để tải code.</li><li><strong>Bảo toàn Portable:</strong> Không sửa các file dùng chung <code>platform-repos.json</code> / <code>legacy-repos.json</code> (chỉ ghi vào bản <code>.local.json</code>).</li><li>Hướng dẫn member chạy lệnh <code>platform-dna codegraph:wire</code> hoặc <code>codegraph init</code> ở các repo chưa có cấu hình.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Đóng vai trò là cầu nối giúp hệ thống FlowGrid (thông qua Platform DNA) biết được mã nguồn của các module/repo thành phần đang nằm ở đâu trên máy tính (Local Workspace) của lập trình viên.</li><li>Rất cần thiết khi bắt đầu thiết lập môi trường (setup environment) để các Agent có thể thực hiện nhảy cross-repo (đọc file từ Docs Hub sang FE/BE và ngược lại) một cách chính xác.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/configure-repo-maps</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',16)])])}const g=o(c,[["render",i]]);export{u as __pageData,g as default};
